const editing=new URLSearchParams(location.search).has('project');
let state={assets:[],projects:[],outputs:[]},timeline=null,selectedAsset=null,selectedClip=null,selectedTrack=null;
let mode='program',playhead=0,zoom=55,snapping=true,razor=false,dragging=false,editingNow=false,refreshing=false;
