function scheduleRenderPoll(delay=10000){clearTimeout(renderPollTimer);renderPollTimer=setTimeout(async()=>{renderPollTimer=null;if(renderPolling){scheduleRenderPoll(1500);return;}renderPolling=true;try{await loadRenders();}catch(e){notice(errorText(e),true);}finally{renderPolling=false;scheduleRenderPoll(renderJobs.some(j=>['queued','running'].includes(j.status))?1500:10000);}},delay);}
function renderChat(node,text){node.replaceChildren();const tokens=String(text).split(/(```[\s\S]*?```|`[^`\n]+`|\*\*[^*\n]+\*\*)/g);for(const token of tokens){if(token.startsWith('```')&&token.endsWith('```')){const code=el('pre',token.slice(3,-3).replace(/^[a-zA-Z0-9_-]+\n/,''));node.append(code);}else if(token.startsWith('`')&&token.endsWith('`'))node.append(el('code',token.slice(1,-1)));else if(token.startsWith('**')&&token.endsWith('**'))node.append(el('strong',token.slice(2,-2)));else node.append(document.createTextNode(token));}}
function chatEvent(event){const {kind,data}=event;if(kind==='text'||kind==='message'){const key=data.item_id||'current';let node=messages.get(key);if(!node){node=el('article','');messages.set(key,node);$('messages').append(node);}node.dataset.raw=kind==='message'?data.text:(node.dataset.raw||'')+data.text;renderChat(node,node.dataset.raw);}else if(kind==='user'){$('messages').querySelector('.welcome')?.remove();$('messages').append(el('article',data.text,'user'));}else if(kind==='activity'){const key=data.item_id||data.tool||data.command||data.type;let node=activities.get(key);if(!node){node=el('article','','activity');activities.set(key,node);$('messages').append(node);}node.textContent=[data.tool||data.type,data.status].filter(Boolean).join(' · ');}else if(kind==='error')$('messages').append(el('article',data.message||JSON.stringify(data),'error'));else if(kind==='notice')$('messages').append(el('article',data.text,'activity'));else if(kind==='finished'){notice('Codex '+(data.status||'finished')+'.');refresh(true).catch(e=>notice(errorText(e),true));}const scroller=$('messages');if(scroller.scrollHeight-scroller.scrollTop-scroller.clientHeight<180||kind==='user')scroller.scrollTop=scroller.scrollHeight;}
let approvalSignature='';
function paintApprovals(list){const signature=JSON.stringify(list);if(signature===approvalSignature)return;approvalSignature=signature;$('approvals').replaceChildren();for(const item of list){const card=el('div',undefined,'approval'),isQuestion=item.method.includes('UserInput');card.append(el('strong',isQuestion?'Codex needs a detail':'Approval request'));const fields={};if(isQuestion){for(const q of item.params.questions||[]){const label=el('label',q.question||q.header);const field=q.options?.length?el('select'):el('input');if(q.options?.length)options(field,q.options.map(o=>o.label));label.append(field);fields[q.id]=field;card.append(label);}}else{card.append(el('p',item.params.reason||item.params.command||'This request requires a response.'));}const send=async accepted=>{const args={ident:item.request_id,accepted};if(isQuestion)args.answers=Object.fromEntries(Object.entries(fields).map(([id,f])=>[id,{answers:[f.value]}]));await api('/api/codex/approve',args);};card.append(button(isQuestion?'Reply':'Approve',()=>send(true)),button('Decline',()=>send(false)));$('approvals').append(card);}}
async function connect(){const r=await api('/api/codex/connect',{});models=r.models;options($('model'),[{value:'',label:'Account default'},...models.map(m=>({value:m.model||m.id,label:m.displayName||m.model||m.id}))],localStorage.getItem('film-model')||'');updateEffort();$('agent-state').textContent='● Connected with ChatGPT';$('connect-codex').textContent='Reconnect';notice('Codex connected · '+$('permissions').selectedOptions[0].textContent);}
function updateEffort(){const m=models.find(m=>(m.model||m.id)===$('model').value);options($('effort'),[{value:'',label:'Default'},...(m?.supportedReasoningEfforts||[]).map(i=>({value:typeof i==='string'?i:i.reasoningEffort,label:typeof i==='string'?i:i.reasoningEffort}))],localStorage.getItem('film-effort')||'');}
async function send(){const text=$('prompt').value.trim();if(!text)return;if(codexBusy)throw new Error('Codex is working. Stop the current turn before sending another.');const args={text,images:[...attached]};if($('model').value)args.model=$('model').value;if($('effort').value)args.effort=$('effort').value;await api('/api/codex/start',args);$('prompt').value='';attached.clear();$('attachments').hidden=true;await poll();}
async function poll(){if(!editing||polling)return;polling=true;try{let r=await api('/api/events?after='+after);if(epoch&&r.epoch!==epoch){after=0;messages.clear();activities.clear();$('messages').replaceChildren();r=await api('/api/events?after=0');}epoch=r.epoch;for(const event of r.events){after=Math.max(after,event.id);chatEvent(event);}window.renderTokenUsage?.(r.token_usage,$('token-meter'));codexBusy=r.busy;paintApprovals(r.approvals);$('stop').hidden=!r.busy;$('send').disabled=r.busy;$('permissions').disabled=r.busy;$('agent-state').textContent=r.busy?'◌ Working':models.length?'● Ready':'○ Connect to begin';}catch(e){notice(errorText(e),true);}finally{polling=false;}}
