// Signed media capabilities rotate before expiry, including after wake from sleep.
let renewingMedia=false;
async function refreshMediaURLs(){if(renewingMedia||!editing)return;renewingMedia=true;let changed=false;try{const renew=async url=>{if(!url)return url;const u=new URL(url,location.href),expiry=Number(u.searchParams.get('expires'));if(!expiry||expiry*1000>Date.now()+300000)return url;return (await api('/api/media-url',{path:u.searchParams.get('path')})).url;};for(const info of [...media.values(),sourceInfo,program,outputInfo].filter(Boolean)){for(const key of ['url','thumbnail','waveform'])if(info[key]){const fresh=await renew(info[key]);if(fresh!==info[key]){info[key]=fresh;changed=true;}}}for(const id of ['video','image']){const node=$(id),old=node.getAttribute('src');if(!old)continue;const fresh=await renew(old);if(fresh!==old&&node.getAttribute('src')===old){const time=node.currentTime||0,playing=id==='video'&&!node.paused;if(id==='video')node.addEventListener('loadedmetadata',()=>{node.currentTime=time;if(playing)node.play().catch(()=>{});},{once:true});node.src=fresh;changed=true;}}if(changed){paintAssets();if(!dragging)drawTimeline();}}finally{renewingMedia=false;}}
setInterval(()=>refreshMediaURLs().catch(e=>notice(errorText(e),true)),60000);
window.addEventListener('focus',()=>refreshMediaURLs().catch(()=>{}));

function startAssetDrag(e,card,a){if(e.button!==0||editingNow||e.target.closest('.asset-delete'))return;e.preventDefault();assetDragging=true;card.focus({preventScroll:true});const x=e.clientX,y=e.clientY;let moved=false,target=null,ghost=null;selectedAsset=a.id;updateAssetSelection();card.setPointerCapture(e.pointerId);function move(ev){if(Math.hypot(ev.clientX-x,ev.clientY-y)<5&&!moved)return;if(!moved){moved=true;assetDragging=true;dragging=true;ghost=el('div',a.name,'asset-drag-ghost');document.body.append(ghost);}ghost.style.left=(ev.clientX+12)+'px';ghost.style.top=(ev.clientY+12)+'px';document.querySelectorAll('.track-strip.drag-over').forEach(n=>n.classList.remove('drag-over'));target=document.elementsFromPoint(ev.clientX,ev.clientY).find(n=>n.classList?.contains('track-strip'))||null;const track=timeline?.tracks.find(t=>t.track_id===target?.dataset.track);if(track&&trackLocked(track))target=null;if(target){target.classList.add('drag-over');$('drop-guide').hidden=false;$('drop-guide').style.left=(136+snapFrame(pointerFrame(ev,target))/fps()*zoom)+'px';}else $('drop-guide').hidden=true;}
async function end(ev){card.removeEventListener('pointermove',move);card.removeEventListener('pointerup',end);card.removeEventListener('pointercancel',cancel);card.removeEventListener('lostpointercapture',cancel);ghost?.remove();document.querySelectorAll('.track-strip.drag-over').forEach(n=>n.classList.remove('drag-over'));$('drop-guide').hidden=true;assetDragging=false;dragging=false;try{if(moved&&target&&ev.type==='pointerup')await addAsset(a,target.dataset.track,snapFrame(pointerFrame(ev,target)));else if(!moved&&ev.type==='pointerup')await selectAsset(a.id);}catch(error){notice(errorText(error),true);}}
function cancel(ev){end(ev);}card.addEventListener('pointermove',move);card.addEventListener('pointerup',end);card.addEventListener('pointercancel',cancel);card.addEventListener('lostpointercapture',cancel);}

